def get_district_list_by_division() -> list:
    """(division_name, [(district_key, district_marathi_name), ...]) असं क्रमवार tuples"""
    result = []
    for division, keys in DIVISIONS.items():
        districts = [(k, MAHARASHTRA_DISTRICTS[k][0]) for k in keys]
        result.append((division, districts))
    return result

def get_talukas(district_key: str) -> list:
    d = MAHARASHTRA_DISTRICTS.get(district_key)
    return d[1] if d else []

def get_district_coords(district_key: str):
    d = MAHARASHTRA_DISTRICTS.get(district_key)
    if not d:
        return (18.5204, 73.8567)  # Pune fallback
    return (d[2], d[3])
